      "record_ids": ["S02-00106", "S02-00108"]
    },
    {
      "claim": "Network-flow records show SMB connections from WS-DWELLS-01 to DC-LV-01 at 13:35 and 13:49 UTC. These records do not identify the accessed share or the purpose of the sessions.",
      "claim_type": "observed_fact",
      "record_ids": ["S02-00075", "S02-00185"]
    }
  ],
  "known_telemetry_limitations": [
    "Coverage reports that Windows Event Forwarding stopped on WS-DWELLS-01 from 13:30 to 14:10 UTC, so Security and Sysmon events were not ingested during the interval containing the download and reported PowerShell activity. The coverage result has no record ID.",
